-- Batch 9b: a SAV refund/exchange returns the sold phone, so the unpaid credit of that sale is cancelled.
-- Additive: no row is changed; only the derived view is redefined. The refund row is the closure event.
DROP VIEW credit_balances;
CREATE VIEW credit_balances AS SELECT c.*,CASE WHEN v.sale_id IS NOT NULL OR EXISTS(SELECT 1 FROM sav_refunds f WHERE f.sale_id=c.sale_id) THEN 0 ELSE c.amount_minor-COALESCE((SELECT sum(r.amount_minor) FROM credit_repayments r WHERE r.sale_id=c.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)),0) END balance_minor,CASE WHEN v.sale_id IS NOT NULL OR EXISTS(SELECT 1 FROM sav_refunds f WHERE f.sale_id=c.sale_id) THEN 'VOID' WHEN c.amount_minor=COALESCE((SELECT sum(r.amount_minor) FROM credit_repayments r WHERE r.sale_id=c.sale_id AND NOT EXISTS(SELECT 1 FROM credit_repayment_reversals x WHERE x.repayment_id=r.id)),0) THEN 'PAID' ELSE 'OPEN' END state FROM sale_credits c LEFT JOIN sale_voids v ON v.sale_id=c.sale_id;
